  32 // Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
  33 // success; on failure prints an error tagged with `ctx` and returns "". The
  34 // existence check lives here, at the one resolver fast/cycle/hybrid share, so a
  35 // missing path fails with a clear "ELF not found" in the driver instead of being
  36 // handed to the engine (e.g. qemu's cryptic "Unable to find the RISC-V BIOS").
  37 std::string abs_elf(const std::string& path, const std::string& ctx) {
  38   std::error_code ec;
  39   fs::path abs = fs::absolute(path, ec);
  40   if (ec) {
  41     std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
  42                  ctx.c_str(), path.c_str());
  43     return "";
  44   }
  45   if (!fs::is_regular_file(abs, ec)) {
  46     std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
  47                  path.c_str());
  48     return "";
  49   }
  50   return abs.string();
  51 }
