  53 // Validate the lone-ELF positional shape the standalone models require: print
  54 // the diagnostic and return 2 on a violation, else 0. `model` labels the error.
  55 int check_one_elf(const Cli& cli, const char* model) {
  56   if (cli.positional.empty()) {
  57     std::fprintf(stderr,
  58                  "andesim run --mode %s: missing ELF (the workload to run; "
  59                  "e.g. a tests/fixtures/<name>.elf)\n",
  60                  model);
  61     return 2;
  62   }
  63   if (cli.positional.size() > 1) {
  64     std::fprintf(stderr,
  65                  "andesim run --mode %s: unexpected argument '%s' "
  66                  "(engine args go after --)\n",
  67                  model, cli.positional[1].c_str());
  68     return 2;
  69   }
  70   return 0;
  71 }
