  73 // Print the dry-run preview: the exact command(s) andesim WOULD spawn, each
  74 // shell-quoted and labeled, executing nothing. Shared by every --mode so the
  75 // preview format is identical; `labels[i]` annotates `argvs[i]` (e.g.
  76 // "fast-leg [qemu]", "standalone [qemu]"). Always returns 0 -- a dry run
  77 // reports the plan, it does not run it.
  78 int print_dry_run(const std::vector<std::vector<std::string>>& argvs,
  79                   const std::vector<std::string>& labels) {
  80   std::printf("[andesim] dry-run: %zu command(s), not executed\n", argvs.size());
  81   for (size_t i = 0; i < argvs.size(); ++i) {
  82     std::printf("# command %zu/%zu: %s\n", i + 1, argvs.size(),
  83                 labels[i].c_str());
  84     std::printf("%s\n", render_argv(argvs[i]).c_str());
  85   }
  86   return 0;
  87 }
