  89 // The standalone spine shared by `fast` and `cycle`: both take a single ELF,
  90 // then run the resolved engine standalone with `extra` framework-injected args
  91 // (e.g. fast's --mem-size `-m`) followed by the post-`--` args forwarded
  92 // verbatim, inheriting stdio (an interactive gdbstub / monitor / semihosting
  93 // console works unchanged) and propagating the exit code. `extra` precedes the
  94 // user's passthrough so a user's own flag wins. The per-model engine +
  95 // selection are resolved by the caller; `model` here only labels the positional
  96 // diagnostics. The ELF is resolved to an absolute, existing path (abs_elf) so a
  97 // missing file fails here in the driver, not later inside the engine.
  98 int run_standalone(const Cli& cli, const EngineDescriptor& eng,
  99                    const char* model, const std::vector<std::string>& extra = {}) {
 100   if (int rc = check_one_elf(cli, model)) return rc;
 101   // QEMU's -bios flag searches its data directory for relative paths rather than
 102   // the CWD; resolving to absolute (and rejecting a missing file) makes both
 103   // QEMU and vsim find the ELF, and fails a typo with a clear "ELF not found".
 104   const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
 105   if (elf.empty()) return 2;
 106   std::vector<std::string> args = extra;
 107   args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
 108   std::string err;
 109   const std::vector<std::string> argv =
 110       passthrough_argv(eng, "standalone", elf, args, err);
 111   if (!err.empty()) {
 112     std::fprintf(stderr, "andesim run: %s\n", err.c_str());
 113     return 2;
 114   }
 115   // --dry-run: print the exact engine command and stop, spawning nothing -- the
 116   // full qemu/vsim standalone command (incl. -bios <elf> and any post-`--`).
 117   if (cli.dry_run)
 118     return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
 119   return exec_passthrough(argv);
 120 }
