 122 // `run --mode fast`: QEMU alone, functional, transparent passthrough. Resolves
 123 // the built-in qemu descriptor directly (no engine discovery -- fast needs only
 124 // qemu, and discover_engines would spawn a --describe per Verilator build).
 125 int run_fast(const Cli& cli) {
 126   // fast is QEMU-only; an explicit engine must name it.
 127   if (!cli.engine.empty() && cli.engine != "qemu") {
 128     std::fprintf(stderr,
 129                  "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
 130                  cli.engine.c_str());
 131     return 2;
 132   }
 133   // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
 134   // default injected). It precedes the post-`--` args, so a user's own -m wins.
 135   std::string err;
 136   std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
 137   if (!err.empty()) {
 138     std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
 139     return 2;
 140   }
 141   // --gdb: launch QEMU with its built-in gdbstub, frozen at reset, so a gdb
 142   // client can attach before the first instruction retires. -s is QEMU's
 143   // shorthand for -gdb tcp::1234; -S halts the CPU at startup. These precede
 144   // the post-`--` args, so an explicit user override still wins.
 145   if (cli.gdb) {
 146     extra.push_back("-s");
 147     extra.push_back("-S");
 148   }
 149   return run_standalone(cli, builtin_qemu(), "fast", extra);
 150 }
