 152 // `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
 153 // no --resume-from-qemu), transparent passthrough -- cycles surface in the
 154 // engine's own output. Unlike fast, this must discover the Verilator build(s)
 155 // to resolve the engine (explicit --engine, else the sole one).
 156 int run_accurate(const Cli& cli) {
 157   // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
 158   // --describe subprocess per Verilator build only to fail on the argument.
 159   if (int rc = check_one_elf(cli, "cycle")) return rc;
 160   // --mem-size is validated but has nothing to size: the cycle engine always
 161   // models its full DRAM window. Say so instead of silently ignoring it.
 162   if (!cli.mem_size.empty()) {
 163     std::string se;
 164     if (parse_size(cli.mem_size, se); !se.empty()) {
 165       std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
 166                    se.c_str());
 167       return 2;
 168     }
 169     std::fprintf(stderr,
 170                  "[andesim] --mem-size: the cycle engine models its full "
 171                  "DRAM window; nothing to size\n");
 172   }
 173   Discovery disc = discover_engines();
 174   std::string err;
 175   const EngineDescriptor* eng =
 176       resolve_accurate_engine(disc.engines, cli.engine, err);
 177   if (!eng) {
 178     std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
 179     // Surface why an expected engine may be absent (failed --describe, etc.).
 180     for (const std::string& w : disc.warnings)
 181       std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
 182     return 2;
 183   }
 184   return run_standalone(cli, *eng, "cycle");
 185 }
