 187 // `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
 188 // handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle figure
 189 // is the vsim mcycle minus QEMU1's drained mcycle. --dry-run prints the exact
 190 // per-leg command lines run_plan assembled and spawns nothing; --verify lands as
 191 // the feature grows.
 192 int run_hybrid(const Cli& cli) {
 193   auto fail = [](const std::string& msg) {
 194     std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
 195     return 2;
 196   };
 197 
 198   if (int rc = check_one_elf(cli, "hybrid")) return rc;
 199 
 200   // Resolve to an absolute, existing ELF through the shared resolver -- the same
 201   // "ELF not found" check fast/cycle get -- BEFORE trigger resolution, so a
 202   // missing file fails as "ELF not found" rather than a trigger error, and
 203   // before pc-boundary resolution reads the ELF's .symtab.
 204   const std::string elf = abs_elf(cli.positional[0], "--mode hybrid");
 205   if (elf.empty()) return 2;
 206 
 207   std::string err;
 208   const Trigger trig = hybrid_trigger(cli, elf, err);
 209   if (!err.empty()) return fail(err);
 210 
 211   // --mem-size sizes the shared mmap (= QEMU backend = vsim window); the 2 GiB
 212   // cap + ELF-fit reject ride the V-scratch work. Empty spec keeps the default.
 213   long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
 214   if (!cli.mem_size.empty()) {
 215     std::string se;
 216     mem = parse_size(cli.mem_size, se);
 217     if (!se.empty()) return fail("--mem-size: " + se);
 218   }
 219 
 220   // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
 221   // or the sole cycle-accurate engine (reusing the F8 selector).
 222   Discovery disc = discover_engines();
 223   const EngineDescriptor* acc =
 224       resolve_accurate_engine(disc.engines, cli.engine, err);
 225   if (!acc) {
 226     std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
 227     for (const std::string& w : disc.warnings)
 228       std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
 229     return 2;
 230   }
 231 
 232   Plan plan;
 233   plan.elf = elf;
 234   plan.mem_size = mem;
 235   plan.steps = {
 236       Step{"qemu", "fast-leg", trig},
 237       Step{acc->id, "accurate-leg", trig},
 238   };
 239 
 240   // Banner to stderr so the window-cycle result stands alone on stdout.
 241   const std::string fixture = fs::path(elf).stem().string();
 242   std::fprintf(stderr, "[andesim] model=hybrid engine=%s trigger=%s fixture=%s\n",
 243                acc->id.c_str(), trig.kind.c_str(), fixture.c_str());
 244 
 245   PlanOptions opts;
 246   opts.dry_run = cli.dry_run;
 247   const PlanResult r = run_plan(plan, disc.engines, opts);
 248   if (!r.ok()) {
 249     std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
 250     return 1;
 251   }
 252   // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
 253   // fast leg then the vsim accurate leg -- and stop. Nothing was spawned.
 254   if (cli.dry_run) {
 255     std::vector<std::string> labels;
 256     labels.reserve(plan.steps.size());
 257     for (const Step& s : plan.steps)
 258       labels.push_back(s.role + " [" + s.engine_id + "]");
 259     return print_dry_run(r.argvs, labels);
 260   }
 261   // phases[0] = QEMU1 drain, [1] = vsim drain; the window figure is the vsim
 262   // mcycle delta.
 263   const unsigned long long q_mc = r.phases[0].mcycle;
 264   const unsigned long long v_mc = r.phases[1].mcycle;
 265   std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
 266               trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
 267   std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
 268               fixture.c_str());
 269   return 0;
 270 }
