 274 int cmd_run(const Cli& cli) {
 275   if (cli.model.empty()) {
 276     std::fprintf(stderr,
 277                  "andesim run: --mode fast|cycle|hybrid is required "
 278                  "(pick the composition; see 'andesim run --help')\n");
 279     return 2;
 280   }
 281   if (!find_model(cli.model)) {
 282     std::fprintf(stderr,
 283                  "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
 284                  cli.model.c_str());
 285     return 2;
 286   }
 287   // Post-`--` args are forwarded verbatim to the engine -- but hybrid has TWO
 288   // legs (a QEMU fast-forward + a vsim measure leg) whose command lines the
 289   // handoff builds itself, so there is no single "the engine" to forward to.
 290   // Reject rather than silently drop (the old behavior) or guess a leg. vsim
 291   // options have dedicated flags (--kanata/--objdump); fast/cycle still forward.
 292   if (!cli.passthrough.empty() && cli.model == "hybrid") {
 293     std::fprintf(stderr,
 294                  "andesim run: --mode hybrid takes no `-- <args>` (the handoff "
 295                  "builds both legs' command lines; use --kanata/--objdump for "
 296                  "vsim options, or --mode fast|cycle to forward to one engine)\n");
 297     return 2;
 298   }
 299   // --trigger / --pc-start / --pc-end delimit the hybrid ROI window. --trigger
 300   // is hybrid-only; --pc-start/--pc-end belong to --trigger pc specifically. Any
 301   // other mode/trigger would SILENTLY drop them and hand back a figure for the
 302   // wrong window (fast/cycle: the whole program; hybrid+marker: the marker
 303   // window), so reject instead of measuring something the user did not ask for.
 304   if (!cli.trigger.empty() && cli.model != "hybrid") {
 305     std::fprintf(stderr,
 306                  "andesim run: --trigger applies only to --mode hybrid "
 307                  "(the ROI delimiter); fast/cycle run the whole program\n");
 308     return 2;
 309   }
 310   if (!cli.pc_end.empty() && cli.trigger != "pc") {
 311     std::fprintf(stderr,
 312                  "andesim run: --pc-end applies only to --mode hybrid "
 313                  "--trigger pc\n");
 314     return 2;
 315   }
 316   if (!cli.pc_start.empty() && cli.trigger != "pc") {
 317     std::fprintf(stderr,
 318                  "andesim run: --pc-start applies only to --mode hybrid "
 319                  "--trigger pc\n");
 320     return 2;
 321   }
 322   if (cli.model == "fast") return run_fast(cli);
 323   if (cli.model == "cycle") return run_accurate(cli);
 324   return run_hybrid(cli);  // model validated above; only hybrid remains
 325 }
 326 
 327 }  // namespace andes_sim

