int fork_background(const std::vector<std::string>& argv) {
  if (argv.empty()) return -1;

  pid_t pid = fork();
  if (pid < 0) return -1;

  if (pid == 0) {  // child: inherit all three std streams, then exec
    exec_or_die(argv);
  }

  // parent: return the pid WITHOUT waiting -- the caller execs the foreground
  // debugger while this child (vsim, holding the JTAG port) free-runs.
  return static_cast<int>(pid);
}

